// Minh họa: Custom Webpack Plugin can thiệp lifecycle hook để tạo file build metadata
class BuildMetadataPlugin {
  apply(compiler) {
    compiler.hooks.emit.tapAsync('BuildMetadataPlugin', (compilation, callback) => {
      const metadata = {
        buildTime: new Date().toISOString(),
        chunks: Array.from(compilation.chunks).map(c => ({ name: c.name, size: c.size() })),
      };
      const content = JSON.stringify(metadata, null, 2);
      // Ghi trực tiếp một asset mới vào compilation output
      compilation.assets['build-meta.json'] = {
        source: () => content,
        size: () => content.length,
      };
      callback();
    });
  }
}

module.exports = BuildMetadataPlugin;

