// Xử lý giữ state khi module được hot-reloaded
if (import.meta.hot) {
  // Chấp nhận bản cập nhật của chính module này
  import.meta.hot.accept((newModule) => {
    if (newModule) {
      console.log('[HMR] Module updated without reload!');
    }
  });

  // Dọn dẹp side-effect hoặc timer trước khi module bị thay thế
  import.meta.hot.dispose((data) => {
    data.preservedCount = appState.count;
  });
}

