// Ví dụ so sánh giữa Code KHÔNG Tree-shakeable vs Code TỐI ƯU

// ❌ KHÔNG THỂ TREE-SHAKE:
// 1. Export CommonJS object
module.exports = { add: (a, b) => a + b, subtract: (a, b) => a - b };
// 2. Chứa side-effect ở top-level file
window.__LAST_ACCESSED__ = Date.now();
// 3. Class được biên dịch ra ES5 hàm IIFE tự thực thi
var Calculator = (function () {
  function Calculator() {}
  Calculator.prototype.calc = function () { return 42; };
  return Calculator;
})(); // Bundler sợ IIFE này thay đổi biến ngoài nên không dám xóa!

// ✅ HOÀN TOÀN TREE-SHAKEABLE:
// 1. Sử dụng Named Export tĩnh trong ESM
export const add = (a: number, b: number): number => a + b;
export const subtract = (a: number, b: number): number => a - b;
// 2. Đánh dấu hàm không có side-effect bằng annotation PURE
export const CalculatorPure = /*#__PURE__*/ (function () {
  function CalculatorPure() {}
  return CalculatorPure;
})();
